  "claims": [
    {
      "card_ids": ["C07"],
      "claim": "In a rabbit S. pneumoniae meningitis model, oritavancin showed only 5% CSF penetration relative to plasma, indicating poor CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "In a rabbit meningitis model, oritavancin CSF penetration was low at 1–5%, consistent with inadequate CNS exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "In rabbits, dalbavancin-derived radioactivity in CSF was very low and measurable only at late time points, supporting poor CNS penetration for this closely related agent.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Direct condition-matched evidence in rabbit meningitis models shows very low CSF penetration for the highly similar glycopeptide oritavancin, and the related dalbavancin also shows minimal CSF exposure. This indicates inadequate meaningful CNS access after systemic administration.",
  "evidence_gaps": [
    "No human meningitis pharmacokinetic data are provided for the query molecule.",
    "Low-similarity permeable compounds are not condition-matched and do not override the direct rabbit meningitis evidence."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

